def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = [r for r in range(h)
                  if len(set(grid[r])) == 1 and grid[r][0] != 0]
    objects = []
    for i, top in enumerate(separators):
        bottom = separators[i + 1] if i + 1 < len(separators) else h
        cells = [(r, c) for r in range(top + 1, bottom) for c in range(w)
                 if grid[r][c] not in (0, 5)]
        height = 0
        color = 0
        if cells:
            rows = [r for r, c in cells]
            height = max(rows) - min(rows) + 1
            color = grid[cells[0][0]][cells[0][1]]
        objects.append((height, color))
    gray = next((r for r, row in enumerate(grid) if 5 in row), -1)
    marked = -1
    for i, (top, (height, color)) in enumerate(zip(separators, objects)):
        if separators[i + 1] <= gray:
            marked = i
    out = [[0, 0, 0, 9, 0] for _ in objects]
    for row, (height, color) in enumerate(objects):
        if height:
            width = min(3, (height + 1) // 2)
            for c in range(width):
                out[row][c] = color
    if marked >= 0:
        out[marked][4] = 5
    return out
